	/**
	 * Test that when cpp has no list or reserved that no matter what xhibit combination it will always equal xhibit
	 */
	public void testEmptyCPPs ()  {

		String xml1 = getWithListAndReserve(false, false, XHIBIT, false);
		String xml2 = getWithListAndReserve(false, true, XHIBIT, false);
		String xml3 = getWithListAndReserve(true, false, XHIBIT, false);
		String xml4 = getWithListAndReserve(true, true, XHIBIT, false);

		
		String cpp = getWithListAndReserve(false, false, XHIBIT, false);
		
		try {
			
			Document doc = getDocBuilderWithNoExternals(xml1);
			Document doc2 = getDocBuilderWithNoExternals(xml2);
			Document doc3 = getDocBuilderWithNoExternals(xml3);
			Document doc4 = getDocBuilderWithNoExternals(xml4);

			Document cppDoc = getDocBuilderWithNoExternals(cpp);
			
			FirmListXMLMergeUtils xmlUtils1 = new FirmListXMLMergeUtils();

			Document mergedDocument = xmlUtils1.merge(doc,cppDoc);
			String s1 = transformXml(mergedDocument);
			assertTrue(s1.equals(xml1));

			mergedDocument = xmlUtils1.merge(doc2,cppDoc);
			s1 = transformXml(mergedDocument);
			assertTrue(s1.equals(xml2));
			

			mergedDocument = xmlUtils1.merge(doc3,cppDoc);
			s1 = transformXml(mergedDocument);
			assertTrue(s1.equals(xml3));
			

			mergedDocument = xmlUtils1.merge(doc4,cppDoc);
			s1 = transformXml(mergedDocument);
			assertTrue(s1.equals(xml4));

		} catch(Exception e){
			TestCase.fail();
		}
	}
	
	
	/**
	 * create the xml depedning on type, whether we want list/reserved
	 * @return of the xml
	 */
	private String getWithListAndReserve(boolean withList, boolean withReserved, String type, boolean diffSitt) {
		
		StringBuffer buff = new StringBuffer(CPPListConstants.FIRM_LIST_ENTRY_TAG 
				+ CPPListConstants.FL_DEFAULT_DOC_XHIBIT_ID_TAGS
				+ CPPListConstants.FL_DEFAULT_LIST_HEADER_XHIBIT_TAGS
				+ CPPListConstants.CROWN_COURT_WITH_ADDRESS_TAGS);
				
		if(withList) {
			buff.append(CPPListConstants.COURT_LISTS_ENTRY_TAG);
			if(diffSitt) {
				 buff.append(CPPListConstants.COURT_LIST_DEFAULT_SITTING_06_02);
			} else {
				buff.append(CPPListConstants.COURT_LIST_DEFAULT_SITTING_06_01);
			}
				buff.append(CPPListConstants.COURT_HOUSE_TAGS
					+ CPPListConstants.SITTINGS_ENTRY_TAG
					+ CPPListConstants.SITTING_ENTRY_TAG
					+ CPPListConstants.COURT_ROOM_NUMBER_ENTRY_TAG+"1"+CPPListConstants.COURT_ROOM_NUMBER_END_TAG
					+ CPPListConstants.SEQ_NO_1
					+ CPPListConstants.SITTING_AT_09
					+ CPPListConstants.PRIORITY_T
					+ CPPListConstants.DEFAULT_JUDICIARY
					+ CPPListConstants.HEARINGS_ENTRY_TAG);
			if(XHIBIT.equals(type)) {
				buff.append(CPPListConstants.HEARING_1);
			} else {
				buff.append(CPPListConstants.HEARING_2);

			}
			buff.append(CPPListConstants.HEARINGS_END_TAG
				+ CPPListConstants.SITTING_END_TAG
				+ CPPListConstants.SITTINGS_END_TAG
				+CPPListConstants.COURT_LIST_END_TAG
				+ CPPListConstants.COURT_LISTS_END_TAG);
		} else {
			buff.append(CPPListConstants.COURT_LISTS_BLANK_TAG);
		}
		if(withReserved) {
			buff.append(CPPListConstants.RESERVE_LIST_ENTRY_TAG);
			if(XHIBIT.equals(type)) {
				buff.append(CPPListConstants.HEARING_1);
			} else {
				buff.append(CPPListConstants.HEARING_2);
			}
			buff.append(CPPListConstants.RESERVE_LIST_END_TAG);
		}
		
		buff.append(CPPListConstants.FIRM_LIST_END_TAG);
		return buff.toString();
	}
	
	
	/**
	 * Returns a string containing up to 2 reserve and 2 lists depending on what user asks for
	 * @return String 
	 */
	private String getUpTo2List2Reserved(boolean xhibitList, boolean cppList, boolean xhibitRes, boolean cppRes) {
		StringBuffer buff = new StringBuffer(CPPListConstants.FIRM_LIST_ENTRY_TAG 
				+ CPPListConstants.FL_DEFAULT_DOC_XHIBIT_ID_TAGS
				+ CPPListConstants.FL_DEFAULT_LIST_HEADER_XHIBIT_TAGS
				+ CPPListConstants.CROWN_COURT_WITH_ADDRESS_TAGS);
		
		if(xhibitList || cppList) {
			buff.append(CPPListConstants.COURT_LISTS_ENTRY_TAG);
			if(xhibitList) {

				buff.append(CPPListConstants.COURT_LIST_DEFAULT_SITTING_06_01);
				buff.append(CPPListConstants.COURT_HOUSE_TAGS
						+ CPPListConstants.SITTINGS_ENTRY_TAG
						+ CPPListConstants.SITTING_ENTRY_TAG
						+ CPPListConstants.COURT_ROOM_NUMBER_ENTRY_TAG+"1"+CPPListConstants.COURT_ROOM_NUMBER_END_TAG
						+ CPPListConstants.SEQ_NO_1
						+ CPPListConstants.SITTING_AT_09
						+ CPPListConstants.PRIORITY_T
						+ CPPListConstants.DEFAULT_JUDICIARY
						+CPPListConstants.HEARINGS_ENTRY_TAG
						+CPPListConstants.HEARING_1
						+CPPListConstants.HEARINGS_END_TAG
						+CPPListConstants.SITTING_END_TAG
						+ CPPListConstants.SITTINGS_END_TAG
						+ CPPListConstants.COURT_LIST_END_TAG);
			}
			if(cppList) {
				 buff.append(CPPListConstants.COURT_LIST_DEFAULT_SITTING_06_02);
				 buff.append(CPPListConstants.COURT_HOUSE_TAGS
							+ CPPListConstants.SITTINGS_ENTRY_TAG
							+ CPPListConstants.SITTING_ENTRY_TAG
							+ CPPListConstants.COURT_ROOM_NUMBER_ENTRY_TAG+"1"+CPPListConstants.COURT_ROOM_NUMBER_END_TAG
							+ CPPListConstants.SEQ_NO_1
							+ CPPListConstants.SITTING_AT_09
							+ CPPListConstants.PRIORITY_T
							+ CPPListConstants.DEFAULT_JUDICIARY
							+CPPListConstants.HEARINGS_ENTRY_TAG
							+CPPListConstants.HEARING_2
							+CPPListConstants.HEARINGS_END_TAG
							+CPPListConstants.SITTING_END_TAG
					+ CPPListConstants.SITTINGS_END_TAG
					+ CPPListConstants.COURT_LIST_END_TAG);
			}
			buff.append(CPPListConstants.COURT_LISTS_END_TAG);
		} else {
			buff.append(CPPListConstants.COURT_LISTS_BLANK_TAG);
		}
		
		if(xhibitRes || cppRes) {
			buff.append(CPPListConstants.RESERVE_LIST_ENTRY_TAG);
			if(xhibitRes) {
				buff.append(CPPListConstants.HEARING_1);
			}
			if(cppRes) {
				buff.append(CPPListConstants.HEARING_2);
			}
			
			if(xhibitRes || cppRes) {
				buff.append(CPPListConstants.RESERVE_LIST_END_TAG);
			}
		}
				

		buff.append(CPPListConstants.FIRM_LIST_END_TAG);
		return buff.toString();
	}
		
